command:
// Система передает в макрос переменные actor и item автоматически
if (!actor) return;
// Получаем ранг Телосложения (Выносливости)
const conRank = actor.system.attributes.con.rank;
// Получаем текущие и максимальные универсальные ОД
const currentAp = actor.system.resources.ap_universal.value;
const maxAp = actor.system.resources.ap_universal.max;
// Вычисляем новое значение: текущее + ранг телосложения, 
// но Math.min гарантирует, что мы не превысим maxAp
const newAp = Math.min(currentAp + conRank, maxAp);
// Вычисляем сколько фактически восстановили для красивого уведомления
const restoredAmount = newAp - currentAp;
// Обновляем документ актера
actor.update({
  "system.resources.ap_universal.value": newAp
});
if (restoredAmount > 0) {
    ui.notifications.info(`${actor.name} восстанавливает ${restoredAmount} универсальных ОД!`);
} else {
    ui.notifications.warn(`Очки Действия уже на максимуме!`);
}
